sed -i -e '/<\/motion.div>/i \      {/* Spotify Code Scanner Overlay */}\n      <SpotifyCodeScanner\n        isOpen={isScannerOpen}\n        onClose={() => setIsScannerOpen(false)}\n        onCodeScanned={(track) => {\n          setIsScannerOpen(false);\n          playTrack(track);\n          showToast(`Scanned successfully! Playing ${track.title} by ${track.artist}`);\n        }}\n      />' src/views/SearchView.tsx
